INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('kaeltetelefon-wien-caritas-winternothilfe-2026-obdachlose','Kältetelefon Wien: Caritas startet Winternothilfe ab 28. Oktober','Ab Mittwoch, 28. Oktober, ist das Kältetelefon der Caritas in Wien wieder rund um die Uhr besetzt. Dazu kommen 70 zusätzliche Schlafplätze und mehr Streetwork.','Das **Kältetelefon Wien** der Caritas ist ab Mittwoch, 28. Oktober 2026, wieder in Betrieb. Unter der Nummer **01/480 45 53** können Wienerinnen und Wiener ab diesem Tag rund um die Uhr, an allen sieben Wochentagen, melden, wo sich obdachlose Menschen bei Kälte im Freien aufhalten. Die Caritas der Erzdiözese Wien hat den Start ihrer Winternothilfe am Nationalfeiertag angekündigt. Neben der Hotline umfasst das Paket zusätzliche Notquartiersplätze und einen Ausbau der Straßensozialarbeit.

## Kältetelefon Wien: So funktioniert die Hotline

Wer einen Menschen sieht, der bei niedrigen Temperaturen draußen schläft oder sich offensichtlich ohne Unterkunft im Freien aufhält, kann das Kältetelefon anrufen. Die Meldung geht an die Streetwork-Teams der Caritas, die täglich in Wien unterwegs sind und laut Organisation so rasch wie möglich ausrücken. Vor Ort informieren sie über Hilfsangebote, verteilen Schlafsäcke, warme Kleidung, Hygieneartikel und heiße Getränke und vermitteln auf Wunsch einen warmen Schlafplatz in einem Notquartier.

Wichtig: Die Hotline ersetzt keinen Notruf. Bei einem medizinischen Notfall ist weiterhin die Rettung unter **144** zu verständigen.

Wie stark das Angebot genutzt wird, zeigt die Bilanz des vergangenen Winters. Damals ging die Nummer mehr als 15.500 Mal ein. 490 akut obdachlose Menschen konnten über diesen Weg in ein Notquartier vermittelt werden. Caritas-Direktor Klaus Schwertner betont, die Hilfe könne Leben retten.

## 70 zusätzliche Schlafplätze in Wien

Ganzjährig stellt die Caritas in Wien nach eigenen Angaben 1.890 Plätze bereit – in Notquartieren, Wohnhäusern und im mobil betreuten Wohnen, jeweils mit Beratung und Verpflegung. Für die kalte Jahreszeit kommen nun 70 weitere Plätze hinzu. Sie wurden gemeinsam mit dem Fonds Soziales Wien (FSW) an zwei Caritas-Standorten geschaffen.

Ziel der Winternothilfe ist laut Caritas, dass in den Wintermonaten niemand ohne Unterstützung bleibt. Die Organisation spricht davon, nun in den „Wintermodus“ zu wechseln.

## Kältetelefone in anderen Bundesländern

Auch außerhalb Wiens richtet die Caritas Kältetelefone ein. In den übrigen Bundesländern starten die Hotlines im Laufe des Novembers. Eine Übersicht mit den jeweiligen Nummern und Erreichbarkeiten veröffentlicht die Caritas unter caritas.at/kaeltetelefon.

## Spenden: Was jetzt gebraucht wird

Für die Winternothilfe bittet die Caritas um Geld- und Sachspenden. Besonders gefragt sind:

- Herrenunterwäsche, Socken und Schuhe
- Jacken und warme Winterkleidung
- Isoliermatten und Schlafsäcke
- waschbare Wolldecken
- Rucksäcke

Sachspenden nehmen die Caritas-Sammelstellen, die sogenannten „carlas“, entgegen. Online lassen sich über den Spendenshop wirhelfen.shop konkrete Hilfsgüter finanzieren, etwa eine warme Suppe, ein Schlafsack oder eine Decke. Geldspenden sind mit dem Verwendungszweck „Winternothilfe“ an die Caritas der Erzdiözese Wien möglich.

## Warum Hinschauen wichtig ist

In kalten Nächten kann Schlafen im Freien rasch gefährlich werden. Die Caritas appelliert deshalb an die Bevölkerung, nicht wegzusehen: Wer jemanden bei Kälte draußen bemerkt, soll das Kältetelefon anrufen. Ein Anruf genügt, um Streetworkerinnen und Streetworker auf den Weg zu schicken. Ist eine Person nicht ansprechbar, verletzt oder wirkt sie unterkühlt, gilt: sofort 144 wählen.','chronik','Wien','wien','news','Presseinfo Redaktion','/assets/img/artikel/kaeltetelefon-wien-caritas-winternothilfe-2026-obdachlose.webp','Caritas der Erzdiözese Wien (APA-OTS)','https://www.ots.at/presseaussendung/OTS_20261026_OTS0001/caritas-startet-winternothilfe-kaeltetelefon-mehr-streetwork-und-schlafplaetze-fuer-obdachlose-menschen','published','2026-10-26T11:55:00.000Z','2026-10-26T11:46:27.384Z','Kältetelefon Wien: Caritas-Winternothilfe ab 28.10.','Kältetelefon Wien: Ab 28. Oktober ist die Caritas-Hotline 01/480 45 53 rund um die Uhr erreichbar. So helfen Sie obdachlosen Menschen im Winter.','Kältetelefon Wien','["Kältetelefon Wien","Kältetelefon","Caritas Winternothilfe","Obdachlose Wien","Notschlafstelle Wien","Kältetelefon Nummer Wien","obdachlose Menschen im Winter helfen","Caritas Streetwork Wien","Sachspenden Caritas Wien"]','Kältetelefon Wien: Streetworkerin übergibt Schlafsack an obdachlosen Menschen im Park','A social worker in a dark winter jacket handing a rolled sleeping bag and a thermos to a person sitting on a bench in a Viennese park at dusk, seen from behind, bare autumn trees, cold blue evening light, frost on the grass, Vienna old apartment buildings softly blurred in the background, no text, no logos, no readable signs','[{"q":"Wie lautet die Nummer des Kältetelefons in Wien?","a":"Das Caritas-Kältetelefon ist unter 01/480 45 53 erreichbar, ab 28. Oktober 2026 rund um die Uhr an allen Tagen."},{"q":"Was tun bei einem medizinischen Notfall?","a":"Bei Verletzungen, Bewusstlosigkeit oder Unterkühlung sofort die Rettung unter 144 rufen. Das Kältetelefon ersetzt keinen Notruf."},{"q":"Welche Sachspenden braucht die Caritas?","a":"Gefragt sind unter anderem Schlafsäcke, Isoliermatten, Wolldecken, Jacken, Schuhe, Socken, Herrenunterwäsche und Rucksäcke."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
